from jsonb_to_recordset($json$[{"brand_slug":"mesoestetic","slug":"fast-growing-bamboo-serum","title_zh_hk":"\u901f\u9577\u6960\u7af9\u7cbe\u83ef","title_zh_cn":"\u901f\u957f\u6960\u7af9\u7cbe\u534e","title_en":"Fast-Growing Bamboo Serum","description_zh_hk":"<p>\u6960\u7af9\u70ba\u81ea\u7136\u754c\u751f\u9577\u901f\u5ea6\u6700\u5feb\u7684\u690d\u7269\u4e4b\u4e00\uff0c\u56e0\u901f\u9577\u6960\u7af9\u6709\u52a9\u6bdb\u7af9\u6301\u7e8c\u5438\u53d6\u6240\u9700\u990a\u5206\u53ca\u4e0d\u65b7\u81ea\u6211\u4fee\u5fa9\uff0c\u4f7f\u5176\u81ea\u751f\u901f\u5ea6\u52a0\u5feb\uff0c\u9054\u81f4\u71df\u990a\u98fd\u6eff\uff0c\u56db\u5b63\u9577\u9752\u6548\u679c\u3002\u901f\u9577\u6960\u7af9\u4e0d\u4f46\u4ee4\u808c\u819a\u4e0d\u65b7\u81ea\u751f\uff0c\u66f4\u80fd\u7121\u9593\u65b7\u586b\u88dc\u808c\u819a\u6240\u9700\u990a\u4efd\uff0c\u4ee4\u808c\u819a\u5373\u6642\u6297\u76ba\uff0c\u56de\u5fa9\u5149\u6ed1\u5f48\u6027\uff0c\u91cd\u62fe\u5e74\u8f15\u9752\u6625\u7f8e\u614b\u3002</p>\n<p>\u901f\u9577\u6960\u7af9\u7cbe\u83ef\u6709\u5373\u6642\u589e\u5f37\u808c\u819a\u5f35\u529b\u7684\u6548\u679c\uff0c\u5176\u6709\u6548\u6210\u4efd\u80fd\u4e3b\u52d5\u64ca\u9000\u9762\u90e8\u75b2\u614b\uff0c\u8fc5\u5373\u70ba\u808c\u5e95\u7d30\u80de\u63d0\u4f9b\u7121\u9650\u91cf\u6c34\u4efd\uff0c\u4ee4\u808c\u819a\u98fd\u6eff\u4eae\u767d\u3002\u5176\u4e0d\u65b7\u81ea\u6211\u4fee\u5fa9\u53ca\u7dca\u7dfb\u63d0\u5347\u529f\u6548\uff0c\u6709\u52a9\u64ab\u5e73\u56e0\u808c\u819a\u8001\u5316\u5f15\u8d77\u7684\u7d30\u7d0b\u53ca\u8868\u60c5\u7d0b\uff0c\u9054\u81f4\u7121\u9593\u65b7\u5149\u901f\u6297\u8001\u5316\uff0c\u8b93\u808c\u819a\u8fc5\u901f\u56de\u5fa9\u5e74\u8f15\u7f8e\u614b\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013\u00a0\u00a0 \u91cd\u9ede\u64ca\u9000\u808c\u819a\u75b2\u5026\u8001\u614b</p>\n<p>\u2013\u00a0\u00a0 \u4fc3\u9032\u81a0\u539f\u86cb\u767d\u5408\u6210\u901f\u5ea6\uff0c\u4ee4\u808c\u819a\u6301\u7e8c\u6297\u6c27\u7f8e\u767d</p>\n<p>\u2013\u00a0\u00a0 \u5f37\u6548\u6d88\u9664\u808c\u819a\